/* 08aa: BX=unit, AX/DX=pixel position. A unit with a valid order destination
 * that is human-controlled or flagged 20h shows its order glyph when the order
 * level passes; order codes 1-3 then suppress the element-type glyph, which is
 * otherwise drawn (also when no order glyph qualifies). */
void opeu_overview_unit_draw(uint8_t ds[65536], HostEvent event, uint16_t frame,
                             uint16_t unit, uint16_t x, uint16_t y) {
  ;
  UNIT_ENTRY(unit, x, y);
  SET_SHOW(0);
  SET_SIDE(SIDE_OF(unit));
  if (DESTINATION(unit) &&
      (SIDE_STATUS(SIDE) == 1 || UNIT_BYTE(unit, 21) & 0x20)) {
    SET_CODE(UNIT_BYTE(UNIT, 14));
    SET_LEVEL(UNIT_BYTE(UNIT, 15));
    if (CODE == 1 || CODE == 2 || CODE == 3 || CODE == 13)
      SET_SHOW(!LEVEL);
    else
      SET_SHOW(LEVEL < 100);
    if (SHOW_WORD) {
      SET_GLYPH(ORDER_GLYPH(CODE));
      READ_ORDER(GLYPH);
      RECOLOR(SIDE_OF(UNIT));
      STREAM(ORDER_MASK(GLYPH));
      SET_BUFFER();
      COMPOSE(SPILL_X, SPILL_Y);
      if (CODE == 1 || CODE == 2 || CODE == 3)
        SET_SHOW(0);
    }
  }
  if (SHOW_WORD)
    return;
  SET_GLYPH(ELEMENT_GLYPH(UNIT));
  {
    /* The original keeps this glyph in SI; later frame changes do not apply. */
    uint8_t glyph = GLYPH;
    READ_ELEMENT(glyph);
    RECOLOR(SIDE_OF(UNIT));
    STREAM(ELEMENT_MASK(glyph));
  }
  SET_BUFFER();
  COMPOSE(SPILL_X, SPILL_Y);
}

/* 0a72: redraw overview cell (x,y). Objective marker mode: scenario 4 uses
 * 2/4, others 0x702/0x701, by objective side 0/other. The 40x40 tile byte
 * selects a 32-byte tile in the overview tile segment. */
void opeu_overview_cell_draw(uint8_t ds[65536], HostEvent event, uint16_t frame,
                             uint8_t x, uint8_t y) {
  ;
  CELL_ENTRY(x, y);
  SET_PIXELS(x, y);
  PIXEL();
  RESTORE(TILE(x, y));
  if (FIND_OBJECTIVE(COPY_X, COPY_Y) != 0) {
    if ((SCENARIO & 0x7f) != 4)
      SET_MODE(OBJECTIVE_SIDE(OBJECTIVE) == 0 ? 0x702 : 0x701);
    else
      SET_MODE(OBJECTIVE_SIDE(OBJECTIVE) == 0 ? 2 : 4);
    MASKED();
  }
  if (SIDE_STATUS(CACHED_X) == 1 && MARKED(SAVED_X, SAVED_Y, CACHED_X)) {
    STREAM(MARK_MASK);
    SET_IMAGE(MARK_IMAGE);
    COMPOSE(PIXEL_X, PIXEL_Y);
  }
  if (MAP_CODE(SAVED_X, SAVED_Y) == 10) {
    STREAM(OVERLAY_IMAGE);
    BLIT_OVERLAY();
  }
  if (FIND_UNIT(SAVED_X, SAVED_Y) != 0 && VISIBLE(CELL_UNIT))
    UNIT_DRAW(CELL_UNIT);
}

